        // Maybe if width == length, return length?

        // Let's correct `testWhitespaceAtLimit` first.
        assertEquals(5, TextHelpAppendable.indexOfWrap("12345 ", 5, 0));
    }

    @Test
    public void testMultipleBreaks() {
        String text = "a-b\nc";
        // Width 10.
        // Hyphen at 1, Newline at 3.
        // `testBreakCharacterFoundWithinWidth` showed preference for later break (8 over 3).
        // So it should return 3 (newline).
        int result = TextHelpAppendable.indexOfWrap(text, 10, 0);
        assertEquals(3, result);
    }

    @Test
    public void testTabAsWhitespace() {
        String text = "word\tword";
